//! A Decimal128 `$inc` under the `field` merge policy is exact or refused: a sum is accepted when its exact value
//! is a Decimal128 at some exponent (a coefficient of at most 34 digits once the trailing zeros are dropped, an
//! exponent in range), whatever exponent that needs, and refused (`IncOutOfRange`) when it would round or overflow.
//! Through the public API only.
//!
//! The table `data/decimal_sum_table.tsv` is generated by `data/gen_decimal_sums.py` with Python's `decimal` at
//! 13,000 digits (no code in common with the Rust arithmetic): operands with padded coefficients, exponents up to
//! 6,000 apart, both signs, sums that are and are not representable.

use kimmy_core::ids::NodeId;
use kimmy_core::merge_state::{
    Epoch, JoinOptions, Path, UpdateOp, UpdateRefused, Value, Writer, WriterId,
};

const TABLE: &str = include_str!("data/decimal_sum_table.tsv");

fn p(s: &str) -> Path {
    Path::flat(s).expect("a valid name")
}

fn dec(t: &str) -> Value {
    Value::Decimal128(t.parse::<bson::Decimal128>().unwrap().bytes())
}

/// `{n: a}` then `$inc` by `b`: whether the `$inc` was accepted (`true`), refused with `IncOutOfRange` (`false`).
fn accepted(a: &str, b: &str) -> bool {
    let id = WriterId { node: NodeId::from_bytes([b'A'; 16]), epoch: Epoch::from_u64(0) };
    let mut w = Writer::new(id, JoinOptions::default());
    w.insert(&[(p("n"), dec(a))], 0).unwrap();
    match w.write_update(&[UpdateOp::Inc(p("n"), dec(b))], 0) {
        Ok(Some(_)) => true,
        Err(UpdateRefused::IncOutOfRange(_)) => false,
        other => panic!("{a} + {b}: {other:?}"),
    }
}

/// `1E+39 + 1000000` is exactly `1000000000000000000000000000000001E+6` (34 digits) and `1E+39 - 1000000` is 33
/// nines `E+6`: the coefficient of the second operand carries trailing zeros and the exponents are 39 apart, so
/// aligning at the finer exponent overflows 128 bits although the sum is representable.
#[test]
fn a_sum_that_is_representable_is_accepted_when_the_operands_carry_trailing_zeros() {
    assert!(accepted("1E+39", "1000000E+0"));
    assert!(accepted("1E+39", "-1000000E+0"));
    // and one that is not: the digits do not fit
    assert!(!accepted("1E+39", "1E+0"));
    assert!(!accepted("1E+39", "-1E+0"));
}

#[test]
fn the_sums_of_python_decimal_are_the_sums_the_writer_accepts() {
    let mut rows = 0;
    for (n, line) in TABLE.lines().enumerate() {
        if line.starts_with('#') || line.is_empty() {
            continue;
        }
        let f: Vec<&str> = line.split('\t').collect();
        assert_eq!(f.len(), 3, "row {n}: {line}");
        assert_eq!(accepted(f[0], f[1]), f[2] == "1", "row {n}: {} + {}", f[0], f[1]);
        rows += 1;
    }
    assert!(rows >= 5000, "{rows} rows");
}
